param([switch]$ExecutionAuthorized)
# Prepare matched OFF inputs only. Never runs GenCase, a solver, a reader or another action.
$ErrorActionPreference='Stop';$tests=Split-Path -Parent $PSScriptRoot;$logs=Join-Path $tests 'logs';$seed=Join-Path $tests 'outputs\upl_column_ringdown_off_seed_r1';$record=Join-Path $logs 'upl_column_ringdown_off_r1.inputs.json'
function E([string]$p){$f=Get-Item -LiteralPath $p;[ordered]@{path=$f.FullName;bytes=[long]$f.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function J([string]$p){[IO.File]::ReadAllText($p)|ConvertFrom-Json}
function Need([bool]$ok,[string]$why){if(!$ok){throw $why}}
function V($rows){foreach($e in $rows){Need ($e.path -and $null -ne $e.bytes -and $e.sha256) 'Missing Entry';$a=E $e.path;Need ($a.bytes -eq $e.bytes -and $a.sha256 -ieq $e.sha256) ('Changed artifact: '+$e.path)}}
function Fresh($paths){foreach($p in $paths){Need (!(Test-Path -LiteralPath $p)) ('Retained path protected: '+$p)}}
function Dom([string]$text){$x=New-Object Xml.XmlDocument;$x.PreserveWhitespace=$false;$x.LoadXml($text);return $x}
function OffText([string]$text){
  $before=Dom $text;$path='/case/execution/special/hydromechanics/HydroMechDynamicSeepage';$nodes=$before.SelectNodes($path);Need ($nodes.Count -eq 1 -and $nodes[0].GetAttribute('value') -ceq '1') 'Exactly one ON dynamic master required'
  $on=[regex]'(<HydroMechDynamicSeepage\b[^>]*\bvalue=")1(")';$off=[regex]'(<HydroMechDynamicSeepage\b[^>]*\bvalue=")0(")';Need ($on.Matches($text).Count -eq 1) 'Unique master token required';$changed=$on.Replace($text,'${1}0${2}',1);Need ($off.Matches($changed).Count -eq 1 -and $off.Replace($changed,'${1}1${2}',1) -ceq $text) 'Master-only whole-text inverse differs'
  $inverse=Dom $changed;$n=$inverse.SelectNodes($path);Need ($n.Count -eq 1 -and $n[0].GetAttribute('value') -ceq '0') 'OFF master missing';$n[0].SetAttribute('value','1');Need ($inverse.OuterXml -ceq $before.OuterXml) 'Master-only whole DOM inverse differs';return $changed
}
Need $ExecutionAuthorized 'Root full-read and explicit OFF Prepare authorization required';Fresh @($seed,$record)
$onPath=Join-Path $logs 'upl_column_ringdown_r1.inputs.json';$onEntry=E $onPath;$m=J $onPath
Need ($m.stage -ceq 'upl_column_ringdown_prepare_r1' -and $m.prepared -eq $true -and $m.passed -eq $true -and $m.physical_acceptance -eq $false -and $m.declared_clock_event_only_changes -eq $true -and $m.input_sources_unchanged -eq $true -and @($m.jobs).Count -eq 3) 'Sealed same-clock ON preparation required'
$bindings=@((E $PSCommandPath),(E (Join-Path $tests 'notes\upl_column_ringdown_off_prepare_r1.json')),$onEntry);$plans=@();$fresh=@($seed,$record)
foreach($window in @('smoke','coarse','half')){$found=@($m.jobs|Where-Object{$_.window -ceq $window});Need ($found.Count -eq 1) 'Unique ON window required';$o=$found[0];$factor=if($window -ceq 'half'){2}else{1};$dt=[Math]::Pow(2,$(if($factor -eq 2){-20}else{-19}));$steps=if($window -ceq 'smoke'){2}else{65536*$factor};$samples=if($window -ceq 'smoke'){3}else{1277};$end=if($window -ceq 'smoke'){2*$dt}else{0.125};V @($o.configuration,$o.runtime,$o.initial_BI4,$o.normals)
  Need ($o.master_value -eq 1 -and $o.conductivity_model -eq 0 -and $o.conductivity_Ck -eq 0 -and !$o.initial_particle_fields_rewritten -and $o.declared_clock_event_only_changes -eq $true -and $o.inverse_DOM_exact -eq $true -and $o.dt_s -eq $dt -and $o.end_s -eq $end -and $o.steps -eq $steps -and $o.expected_samples -eq $samples -and @($o.saved_clock_table).Count -eq $samples -and $o.configuration.sha256 -ceq $o.runtime.sha256 -and $o.initial_BI4.sha256 -ceq 'f2836ffeb049fc777de7687608dd5dfbece81f78440bdc01f21890ee3e3fedac' -and $o.normals.sha256 -ceq '0509139e4fee0c57d3b480f213c4b9062cf467ce6a24c0a1d13d87148a885f97') 'Retained ON identity/clock/material differs'
  $text=[IO.File]::ReadAllText($o.runtime.path);$changed=OffText $text;$configuration=Join-Path $tests ('configs\upl_column_ringdown_off_'+$window+'_r1.xml');$fresh+=$configuration;$bindings+=@($o.configuration,$o.runtime,$o.initial_BI4,$o.normals);$plans+=@{old=$o;configuration=$configuration;text=$changed}
}
Fresh $fresh;V $bindings;$jobs=@();$files=@();$failure=$null;$unchanged=$false
try{[void](New-Item -ItemType Directory -Path $seed);foreach($p in $plans){$o=$p.old;[IO.File]::WriteAllText($p.configuration,$p.text,(New-Object Text.UTF8Encoding($false)));Need ([IO.File]::ReadAllText($p.configuration) -ceq $p.text) 'Saved master-only text differs'
  $prefix=Join-Path $seed ('upl_column_ringdown_off_'+$o.window+'_r1');$runtime=$prefix+'.xml';$bi4=$prefix+'.bi4';$normal=$prefix+'_Normals.nbi4';Fresh @($runtime,$bi4,$normal);Copy-Item -LiteralPath $p.configuration -Destination $runtime;Copy-Item -LiteralPath $o.initial_BI4.path -Destination $bi4;Copy-Item -LiteralPath $o.normals.path -Destination $normal;$ce=E $p.configuration;$re=E $runtime;$be=E $bi4;$ne=E $normal
  Need ($ce.sha256 -ceq $re.sha256 -and $ce.bytes -eq $re.bytes -and $be.sha256 -ceq $o.initial_BI4.sha256 -and $be.bytes -eq $o.initial_BI4.bytes -and $ne.sha256 -ceq $o.normals.sha256 -and $ne.bytes -eq $o.normals.bytes) 'OFF prepared runtime/binary copy differs'
  $jobs+=@{window=$o.window;backend='GPU';configuration=$ce;runtime=$re;input_prefix=$prefix;initial_BI4=$be;normals=$ne;dt_s=$o.dt_s;end_s=$o.end_s;steps=$o.steps;expected_samples=$o.expected_samples;required_CLI=$o.required_CLI;retained_manifest=$onEntry;retained_configuration=$o.configuration;retained_runtime=$o.runtime;retained_initial_BI4=$o.initial_BI4;retained_normals=$o.normals;declared_master_only_change=$true;inverse_DOM_exact=$true;inverse_whole_text_exact=$true;master_value=0;conductivity_model=0;conductivity_Ck=0;initial_particle_fields_rewritten=$false;ramp_and_drain_event_s=$o.ramp_and_drain_event_s;event_completed_step=$o.event_completed_step;saved_clock_table=$o.saved_clock_table;special_timeout=$o.special_timeout;scheduler_preflight=$o.scheduler_preflight};$files+=@($ce,$re,$be,$ne)
}}catch{$failure=$_.Exception.Message}
try{V $bindings;V $files;$unchanged=$true}catch{if(!$failure){$failure=$_.Exception.Message}}
$passed=(!$failure -and $unchanged -and $jobs.Count -eq 3 -and $files.Count -eq 12);$value=[ordered]@{stage='upl_column_ringdown_off_prepare_r1';passed=[bool]$passed;prepared=[bool]$passed;scope='Master-only matched legacy u-pw OFF input preparation, not execution admission';author=(E $PSCommandPath);note=(E (Join-Path $tests 'notes\upl_column_ringdown_off_prepare_r1.json'));retained_ON_manifest=$onEntry;seed_directory=$seed;jobs=$jobs;inputs=$bindings;bindings=$bindings;files=$files;declared_master_only_change=[bool]$passed;input_sources_unchanged=$unchanged;source_replayed_schedule_preflight=$m.source_replayed_schedule_preflight;GenCase_invoked=$false;solver_reader_or_build_invoked=$false;formal_files_changed=$false;physical_acceptance=$false;failure=$failure}
Fresh @($record);[IO.File]::WriteAllText($record,($value|ConvertTo-Json -Depth 18)+[Environment]::NewLine,(New-Object Text.UTF8Encoding($false)));if(!$passed){throw "OFF Prepare failed; preserve fresh partials and $record; no automatic retry"};Write-Output "Matched OFF inputs prepared without a program: $record"
